import 'dart:convert';import 'dart:io';import 'package:flutter/material.dart';import 'package:path/path.dart' as p;import 'package:xml/xml.dart';import '../../core/addons/domain/installed_addon.dart';
class LegacyAddonSettingsPage extends StatefulWidget{const LegacyAddonSettingsPage({required this.addon,required this.addonDataRootPath,super.key});final InstalledAddon addon;final String addonDataRootPath;@override State<LegacyAddonSettingsPage>createState()=>_State();}
class _State extends State<LegacyAddonSettingsPage>{final Map<String,String> values={};List<_Def> defs=[];bool loading=true;File get file=>File(p.join(widget.addonDataRootPath,widget.addon.manifest.id,'settings.json'));@override void initState(){super.initState();_load();}Future<void>_load()async{final candidates=[File(p.join(widget.addon.installPath,'resources','settings.xml')),File(p.join(widget.addon.installPath,'resources','settings','settings.xml'))];File? src;for(final f in candidates){if(await f.exists()){src=f;break;}}if(src!=null){final doc=XmlDocument.parse(await src.readAsString());for(final e in doc.descendants.whereType<XmlElement>().where((x)=>x.name.local=='setting')){final id=e.getAttribute('id');if(id!=null&&id.isNotEmpty)defs.add(_Def(id,e.getAttribute('label')??id,e.getAttribute('type')??'text',e.getAttribute('default')??''));}}if(await file.exists()){try{final d=jsonDecode(await file.readAsString());if(d is Map){for(final e in d.entries){values[e.key.toString()]=e.value.toString();}}}catch(_){}}for(final d in defs){values.putIfAbsent(d.id,()=>d.defaultValue);}if(mounted)setState(()=>loading=false);}Future<void>_save()async{await file.parent.create(recursive:true);await file.writeAsString(const JsonEncoder.withIndent('  ').convert(values),flush:true);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Configurações salvas.')));}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text('Configurações • ${widget.addon.manifest.name}'),actions:[IconButton(onPressed:_save,icon:const Icon(Icons.save_rounded))]),body:loading?const Center(child:CircularProgressIndicator()):defs.isEmpty?const Center(child:Text('Este addon não declarou configurações em settings.xml.')):ListView(padding:const EdgeInsets.all(24),children:[for(final d in defs)Padding(padding:const EdgeInsets.only(bottom:16),child:d.isBool?SwitchListTile(title:Text(d.label),value:(values[d.id]??'').toLowerCase()=='true'||values[d.id]=='1',onChanged:(v)=>setState(()=>values[d.id]=v?'true':'false')):TextFormField(initialValue:values[d.id],decoration:InputDecoration(labelText:d.label,helperText:d.id,border:const OutlineInputBorder()),onChanged:(v)=>values[d.id]=v))]));}
class _Def{_Def(this.id,this.label,this.type,this.defaultValue);final String id,label,type,defaultValue;bool get isBool=>['bool','boolean','toggle'].contains(type.toLowerCase());}
